), updated as (
  update data_vault.municipality_layer_records r
  set payload = jsonb_set(r.payload, '{management_benchmark}', s.benchmark, true),
      source_label = 'SEGEPLAN · Ranking de la Gestión Municipal 2020–2021',
      updated_at = now()
  from source_rows s
  join public.municipalities m
    on m.country_code = 'GT'
   and m.municipality_code = s.municipality_code
   and m.is_synthetic = false
  where r.municipality_id = m.id
    and r.layer_id = 'RGM_SERVICIOS'
    and r.period = '2020-2021'
  returning s.municipality_code
)
select count(*) as updated_rows
from updated;

do $$
begin
  if (
    select count(*)
    from data_vault.municipality_layer_records r
    join public.municipalities m on m.id = r.municipality_id
    where m.municipality_code in ('0701','0702','0703','0704','0705','0706','0707','0708','0709','0710','0711','0712','0713','0714','0715','0716','0717','0718','0719','0801','0802','0803','0804','0805','0806','0807','0808','0901','0902','0903','0904','0905','0906','0907','0908','0909','0910','0911','0912','0913','0914','0915','0916','0917','0918','0919','0920','0921','0922','0923','0924','1001','1002','1003','1004','1005','1006','1007','1008','1009','1010','1011','1012','1013','1014','1015','1016','1017','1018','1019','1020','1021','1101','1102','1103','1104','1105','1106','1107','1108','1109','1201','1202','1203','1204')
      and r.layer_id = 'RGM_SERVICIOS'
      and r.period = '2020-2021'
      and r.payload->'management_benchmark'->>'municipality_code' = m.municipality_code
      and jsonb_array_length(r.payload->'management_benchmark'->'dimensions') = 6
  ) <> 85 then
    raise exception 'RGM benchmark part 02 failed reconciliation';
  end if;
end
$$;

